import * as THREE from './vendor/three.module.js';
import {furniture,euro} from './data.js';
import {t} from './locale.js';
const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
export function createPlacement(container,notify){
 container.innerHTML=`<div id="placement-canvas"><span class="placement-badge">ROOM-ONLY · DRAUFSICHT · FLUR AUSGEBLENDET</span><div class="placement-help">Möbel ziehen · Oder Position über Regler ändern</div></div><aside class="placement-panel" aria-label="Möbel platzieren"><div class="furniture-choices"><button data-furniture="chair" class="active" aria-pressed="true">Sessel</button><button data-furniture="table" aria-pressed="false">Beistelltisch</button></div><h3 id="furniture-name">Lounge 01</h3><p id="furniture-size" class="product-meta">78 × 82 × 86 cm · Beispielmöbel</p><div class="furniture-price" id="furniture-price">249 € <small>Demo-Neupreis</small></div><fieldset class="color-field"><legend>Materialfarbe</legend><div class="color-options"><button data-color="#769c7c" style="--swatch:#769c7c" class="active" aria-label="Farbe Waldgrün" aria-pressed="true"></button><button data-color="#c1936d" style="--swatch:#c1936d" aria-label="Farbe Karamell" aria-pressed="false"></button><button data-color="#d6d4c8" style="--swatch:#d6d4c8" aria-label="Farbe Kreide" aria-pressed="false"></button></div></fieldset><div class="range-field"><label for="furniture-x">Links / rechts <output id="furniture-x-value">0,00 m</output></label><input type="range" min="-1.4" max="1.4" step=".05" value="0" id="furniture-x"></div><div class="range-field"><label for="furniture-z">Vorne / hinten <output id="furniture-z-value">0,00 m</output></label><input type="range" min="-.85" max=".85" step=".05" value="0" id="furniture-z"></div><div class="range-field"><label for="furniture-rotation">Drehung <output id="furniture-rotation-value">0°</output></label><input type="range" min="0" max="360" step="5" value="0" id="furniture-rotation"></div><div class="placement-actions"><button id="animate-furniture">▷ Demo abspielen</button><button id="reset-furniture">Zurücksetzen</button></div><a class="placement-shop" id="furniture-shop" target="_blank" rel="noopener noreferrer" href="https://www.ikea.com/de/de/search/?q=Sessel">Ähnliche Sessel suchen ↗</a><p class="placement-shop-note">Beispielmöbel im selben Raumlayout; der Flur bleibt ausgeblendet. Externe Produktsuche; kein Affiliate-Link.</p></aside>`;
 const localizePlacement=()=>{container.querySelector('.placement-badge').textContent=t('placementBadge');container.querySelector('.placement-help').textContent=t('placementHelp');container.querySelector('.placement-panel').setAttribute('aria-label',t('placementPanel'));container.querySelector('[data-furniture="chair"]').textContent=t('chair');container.querySelector('[data-furniture="table"]').textContent=t('table');container.querySelector('.color-field legend').textContent=t('material');container.querySelector('[data-color="#769c7c"]').setAttribute('aria-label',t('forest'));container.querySelector('[data-color="#c1936d"]').setAttribute('aria-label',t('caramel'));container.querySelector('[data-color="#d6d4c8"]').setAttribute('aria-label',t('chalk'));container.querySelector('label[for="furniture-x"]').firstChild.textContent=t('leftRight')+' ';container.querySelector('label[for="furniture-z"]').firstChild.textContent=t('frontBack')+' ';container.querySelector('label[for="furniture-rotation"]').firstChild.textContent=t('rotation')+' ';container.querySelector('#animate-furniture').textContent=t('playDemo');container.querySelector('#reset-furniture').textContent=t('reset');container.querySelector('.placement-shop-note').textContent=t('placementNote');};localizePlacement();
 const host=container.querySelector('#placement-canvas');
 let renderer;
 try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});}catch{host.innerHTML=`<div class="viewer-error"><strong>${t('webgl')}</strong><p>${t('webglBody')}</p></div>`;container.querySelectorAll('input,button').forEach(b=>b.disabled=true);return {stop(){},play(){notify(t('webglToast'));},dispose(){}};}
 renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.setClearColor('#b8c1b5');renderer.outputColorSpace=THREE.SRGBColorSpace;host.append(renderer.domElement);renderer.domElement.setAttribute('aria-label','3D-Beispielraum mit beweglichem Möbelstück');renderer.domElement.setAttribute('role','img');
 const scene=new THREE.Scene();const camera=new THREE.OrthographicCamera(-2.2,2.2,1.7,-1.7,.1,40);camera.position.set(0,8,0);camera.lookAt(0,0,0);
 scene.add(new THREE.HemisphereLight(0xffffff,0x677764,2.5));const sun=new THREE.DirectionalLight(0xfff9ed,3.2);sun.position.set(-3,7,5);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-5;sun.shadow.camera.right=5;sun.shadow.camera.top=5;sun.shadow.camera.bottom=-5;sun.shadow.bias=-.0006;scene.add(sun);
 const floorMat=new THREE.MeshStandardMaterial({color:'#d0d3c6',roughness:.95});const wallMat=new THREE.MeshStandardMaterial({color:'#e0e2d7',roughness:1});const darkMat=new THREE.MeshStandardMaterial({color:'#33463c',roughness:.75});const wood=new THREE.MeshStandardMaterial({color:'#84694f',roughness:.7});let cloth=new THREE.MeshStandardMaterial({color:'#769c7c',roughness:1});
 function box(w,h,d,x,y,z,mat,parent=scene){let mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);return mesh;}
 box(4,.12,3,0,-.08,0,floorMat);
 box(3.96,.035,.035,0,.01,-1.47,darkMat);box(.035,.035,2.97,-1.97,.01,0,darkMat);
 const grid=new THREE.GridHelper(4,16,0x8ca293,0xa6b6a6);grid.position.y=.002;grid.scale.z=.75;grid.material.transparent=true;grid.material.opacity=.32;scene.add(grid);
 // A low perimeter line keeps the top view legible while excluding the hallway.
 box(4,.06,.04,0,.02,-1.47,darkMat);box(.04,.06,3,-1.97,.02,0,darkMat);box(4,.06,.04,0,.02,1.47,darkMat);box(.04,.06,3,1.97,.02,0,darkMat);
 const objectGroup=new THREE.Group();scene.add(objectGroup);const selection=new THREE.Mesh(new THREE.RingGeometry(.57,.585,64),new THREE.MeshBasicMaterial({color:0x47694c,side:THREE.DoubleSide}));selection.rotation.x=-Math.PI/2;selection.position.y=.011;scene.add(selection);
 let kind='chair',animation=0,raf=0,active=true,dragging=false,dragOffset=new THREE.Vector3(),selectedColor='#769c7c';
 function cylinder(radius,h,x,y,z,material,parent=objectGroup){const m=new THREE.Mesh(new THREE.CylinderGeometry(radius,radius,h,32),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
 function cushion(w,h,d,x,y,z){const m=new THREE.Mesh(new THREE.SphereGeometry(1,32,16),cloth);m.scale.set(w/2,h/2,d/2);m.position.set(x,y,z);m.castShadow=true;objectGroup.add(m);}
 function clear(){while(objectGroup.children.length){const c=objectGroup.children[0];objectGroup.remove(c);c.traverse(n=>{if(n.geometry)n.geometry.dispose();});}}
 function create(kindNext){clear();kind=kindNext;if(kind==='chair'){for(const x of [-.28,.28])for(const z of [-.28,.28])cylinder(.029,.29,x,.145,z,wood);box(.68,.12,.69,0,.31,0,cloth,objectGroup);cushion(.7,.23,.72,0,.415,.035);box(.66,.36,.16,0,.61,-.3,cloth,objectGroup);cushion(.7,.47,.25,0,.64,-.29);box(.09,.22,.69,-.345,.52,.015,cloth,objectGroup);box(.09,.22,.69,.345,.52,.015,cloth,objectGroup);}else{cylinder(.3,.065,0,.4175,0,cloth);for(let a=0;a<3;a++){const angle=a*Math.PI*2/3;cylinder(.025,.39,Math.cos(angle)*.2,.195,Math.sin(angle)*.2,wood);}}
 const spec=furniture[kind];container.querySelector('#furniture-name').textContent=kind==='chair'?t('chair')+' 01':t('table')+' 02';container.querySelector('#furniture-size').textContent=spec.size+' · '+t('exampleFurniture');container.querySelector('#furniture-price').textContent=euro(spec.price)+' · '+t('newPrice');container.querySelectorAll('[data-furniture]').forEach(b=>{b.classList.toggle('active',b.dataset.furniture===kind);b.setAttribute('aria-pressed',String(b.dataset.furniture===kind));});const shop=container.querySelector('#furniture-shop');shop.textContent=kind==='chair'?t('similarSearchChair'):t('similarSearchTable');shop.href=`https://www.ikea.com/de/de/search/?q=${kind==='chair'?'Sessel':'Beistelltisch'}`;localizePlacement();render();}
 function render(){renderer.render(scene,camera);}
 const controls={x:container.querySelector('#furniture-x'),z:container.querySelector('#furniture-z'),rotation:container.querySelector('#furniture-rotation')};
 function update(){objectGroup.position.x=Number(controls.x.value);objectGroup.position.z=Number(controls.z.value);objectGroup.rotation.y=Number(controls.rotation.value)*Math.PI/180;selection.position.x=objectGroup.position.x;selection.position.z=objectGroup.position.z;for(const key of ['x','z'])container.querySelector(`#furniture-${key}-value`).textContent=Number(controls[key].value).toLocaleString('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2})+' m';container.querySelector('#furniture-rotation-value').textContent=controls.rotation.value+'°';render();}
 function stop(){cancelAnimationFrame(raf);animation=0;container.querySelector('#animate-furniture').textContent=t('playDemo');}
 function play(){if(animation){stop();return;}animation=performance.now();container.querySelector('#animate-furniture').textContent=t('stopDemo');const tick=now=>{if(!active){stop();return;}const t=Math.min((now-animation)/6500,1);controls.x.value=String(-1.2+2.15*(t*t*(3-2*t)));controls.z.value=String(-.55+.95*Math.sin(t*Math.PI/2));controls.rotation.value=String(Math.round(t*90/5)*5);update();if(t<1){raf=requestAnimationFrame(tick);}else{stop();notify(t('placementDone'));}};raf=requestAnimationFrame(tick);}
 Object.values(controls).forEach(input=>input.addEventListener('input',()=>{stop();update();}));container.querySelectorAll('[data-furniture]').forEach(b=>b.addEventListener('click',()=>{stop();create(b.dataset.furniture);}));
 container.querySelectorAll('[data-color]').forEach(b=>b.addEventListener('click',()=>{selectedColor=b.dataset.color;cloth.color.set(selectedColor);container.querySelectorAll('[data-color]').forEach(c=>{c.classList.toggle('active',c===b);c.setAttribute('aria-pressed',String(c===b));});render();}));container.querySelector('#animate-furniture').addEventListener('click',play);container.querySelector('#reset-furniture').addEventListener('click',()=>{stop();Object.values(controls).forEach(i=>i.value='0');selectedColor='#769c7c';cloth.color.set(selectedColor);container.querySelectorAll('[data-color]').forEach(c=>{c.classList.toggle('active',c.dataset.color===selectedColor);c.setAttribute('aria-pressed',String(c.dataset.color===selectedColor));});create('chair');update();notify(t('resetDone'));});
 const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),plane=new THREE.Plane(new THREE.Vector3(0,1,0),0),point=new THREE.Vector3();
 function ray(event){const rect=renderer.domElement.getBoundingClientRect();pointer.set((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1);raycaster.setFromCamera(pointer,camera);}
 renderer.domElement.addEventListener('pointerdown',e=>{ray(e);if(!raycaster.intersectObjects(objectGroup.children,true).length)return;stop();dragging=true;renderer.domElement.setPointerCapture(e.pointerId);raycaster.ray.intersectPlane(plane,point);dragOffset.copy(objectGroup.position).sub(point);renderer.domElement.style.cursor='grabbing';});
 renderer.domElement.addEventListener('pointermove',e=>{ray(e);if(!dragging){renderer.domElement.style.cursor=raycaster.intersectObjects(objectGroup.children,true).length?'grab':'default';return;}if(raycaster.ray.intersectPlane(plane,point)){controls.x.value=String(clamp(point.x+dragOffset.x,-1.4,1.4));controls.z.value=String(clamp(point.z+dragOffset.z,-.85,.85));update();}});
 for(const event of ['pointerup','pointercancel','lostpointercapture'])renderer.domElement.addEventListener(event,()=>{dragging=false;renderer.domElement.style.cursor='default';});
 const observer=new ResizeObserver(()=>{const w=host.clientWidth,h=host.clientHeight;if(w&&h){renderer.setSize(w,h);const aspect=w/h;const halfH=1.72,halfW=halfH*aspect;camera.left=-halfW;camera.right=halfW;camera.top=halfH;camera.bottom=-halfH;camera.position.set(0,8,0);camera.lookAt(0,0,0);camera.updateProjectionMatrix();render();}});observer.observe(host);create('chair');update();
 renderer.domElement.setAttribute('aria-label',t('reticleLabel'));renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();stop();notify(t('graphicsPaused'));});
 return{stop,play,setLanguage(){localizePlacement();create(kind);},setActive(value){active=value;if(!value)stop();else render();},dispose(){stop();observer.disconnect();scene.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose();}});renderer.dispose();}};
}
